// Turn the funnel into something a person can read over coffee.
// Every number here comes from decisions this system actually made — no
// assumptions, which is the same standard the pitch deck's projection slide
// holds itself to.
const s = $input.first().json;
const rupee = (n) => '₹' + Number(n).toLocaleString('en-IN');
const date = new Date().toISOString().slice(0, 10);

const gates = s.withheldByGate.length
  ? s.withheldByGate.map((g) => `| ${g.gate} | ${g.count} |`).join('\n')
  : '| _none_ | 0 |';

const products = s.byProduct.length
  ? s.byProduct.map((p) => `| ${p.product} | ${p.count} |`).join('\n')
  : '| _none_ | 0 |';

const markdown = `# One-Tap Credit — daily digest
_${date} · last ${s.sinceDays} day(s) · generated ${s.generatedAt}_

## Funnel
| Step | Count |
| --- | --- |
| Transactions assessed | ${s.totals.transactions} |
| Nudges shown | ${s.totals.nudged} |
| Withheld | ${s.totals.withheld} |
| Accepted | ${s.totals.accepted} |
| Declined | ${s.totals.declined} |

**Nudge rate** ${s.nudgeRate}% · **Acceptance rate** ${s.acceptanceRate}%
Average relevance ${s.averages.score}/100 · average eligibility signal ${s.averages.eligibilitySignal}/100

## Why offers were withheld
| Gate | Count |
| --- | --- |
${gates}

## Product mix
| Product | Count |
| --- | --- |
${products}

---
The engine withheld an offer ${s.totals.withheld} of ${s.totals.transactions} times.
Restraint is the product working, not the product failing.
`;

return [{ json: { markdown, fileName: `digest-${date}.md` } }];
